svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg";
  // Couleurs et épaisseurs reprises du dessin Inkscape ; INS = nucléotides insérés
  var COL = { line: "#000000", bg: "#ffffff", V: "#ed1c24", J: "#fff34f", C: "#008ccf", L: "#ffffff", INS: "#a874c9", D: "#39b54a", cut: "#d1366b" };
  var RIB_OUT = 2.49, RIB_IN = 1.69, H = 7.35 / 2, SW = 0.4;
  // Durées (s) : pause sur chaque étape, puis transition vers la suivante. Boucle infinie.
  // HOLDS[k] = pause au début de l'étape k ; pas de pause avant les étapes 4 et 5 pour que le gène
  // apparaisse dès que sa ligne de texte s'affiche. END_HOLD = temps passé sur l'image finale.
  var HOLDS = [1.0, 1.0, 1.0, 0, 0, 1.0], MOVES = [2.8, 1.8, 1.8, 1.2, 1.2, 2.0], END_HOLD = 6.0;

  // Géométrie (mm). Le brin part déroulé sur une seule ligne y=112.5
  var Y = 112.5, X0 = 26.5;
  var LA = 54, LB = 75.7, LC = 99.6;           // A : début → Vλ2 ; B : ADN excisé ; C : Jλ1 → fin
  var XJ = X0 + LA;                             // fin de A = 80.5
  var GAP = 8;                                  // écart entre les deux pieds de la boucle formée
  var TRIM_A = 2.6, TRIM_C = 1.2;               // longueur rongée sur chaque extrémité (RSS + bout du gène)
  var C_FINAL = 80.7;                           // début de C après jonction (laisse 4 mm d'insertion)
  var NA = 140, NB = 260, NC = 240;

  function $(id) { return document.getElementById(id); }
  function el(tag, attrs, parent) {
    var e = document.createElementNS(NS, tag);
    for (var a in attrs) e.setAttribute(a, attrs[a]);
    if (parent) parent.appendChild(e);
    return e;
  }
  function clamp(x) { return Math.max(0, Math.min(1, x)); }
  function ease(x) { x = clamp(x); return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
  function lerpPts(a, b, f) { return a.map(function (p, i) { return [p[0] + (b[i][0] - p[0]) * f, p[1] + (b[i][1] - p[1]) * f]; }); }

  function resample(poly, n) {
    var d = [0];
    for (var i = 1; i < poly.length; i++) d.push(d[i - 1] + Math.hypot(poly[i][0] - poly[i - 1][0], poly[i][1] - poly[i - 1][1]));
    var L = d[d.length - 1], out = [], j = 0;
    for (var k = 0; k < n; k++) {
      var s = L * k / (n - 1);
      while (j < poly.length - 2 && d[j + 1] < s) j++;
      var seg = d[j + 1] - d[j] || 1, f = (s - d[j]) / seg;
      out.push([poly[j][0] + (poly[j + 1][0] - poly[j][0]) * f, poly[j][1] + (poly[j + 1][1] - poly[j][1]) * f]);
    }
    return out;
  }
  function samplePath(d, n) {
    var p = el("path", { d: d }, $("measure"));
    var L = p.getTotalLength(), pts = [];
    for (var i = 0; i < n; i++) { var q = p.getPointAtLength(L * i / (n - 1)); pts.push([q.x, q.y]); }
    p.parentNode.removeChild(p);
    return pts;
  }

  function line(x0, len, n) {
    var out = [];
    for (var i = 0; i < n; i++) out.push([x0 + len * i / (n - 1), Y]);
    return out;
  }

  // Boucle de B : on définit l'angle de la tangente le long du brin pour la boucle finale
  // (petit col, descente, ballon), puis chaque étape intermédiaire multiplie ces angles par k.
  // k = 0 donne une ligne droite, k = 1 la boucle ; la forme reste lisse et symétrique, et les
  // deux pieds restent sur la ligne tout du long.
  var RHO = 2.5, NECK = 3.0, RHO2 = 3.0;
  function loopProfile(gam) {
    var segs = [[RHO * Math.PI / 2, 0, Math.PI / 2], [NECK, Math.PI / 2, Math.PI / 2], [RHO2 * gam, Math.PI / 2, Math.PI / 2 + gam]];
    var used = segs.reduce(function (a, g) { return a + g[0]; }, 0);
    segs.push([LB / 2 - used, Math.PI / 2 + gam, 0]);
    var n = NB - 1, ds = LB / n, half = [];
    for (var i = 0; i < n / 2; i++) {
      var s = (i + 0.5) * ds, acc = 0;
      for (var j = 0; j < segs.length; j++) {
        if (s <= acc + segs[j][0] || j === segs.length - 1) { var f = Math.min(1, (s - acc) / segs[j][0]); half.push(segs[j][1] + (segs[j][2] - segs[j][1]) * f); break; }
        acc += segs[j][0];
      }
    }
    var th = half.slice();
    for (var m = half.length - 1; m >= 0; m--) th.push(-half[m]);
    return th.slice(0, n);
  }
  function bend(th, k) {
    var n = th.length, ds = LB / n, out = [[XJ, Y]], x = XJ, y = Y;
    for (var i = 0; i < n; i++) { x += Math.cos(th[i] * k) * ds; y += Math.sin(th[i] * k) * ds; out.push([x, y]); }
    return out;
  }
  var THETA = (function () {
    var lo = 0, hi = Math.PI / 2;
    for (var it = 0; it < 50; it++) {
      var g = (lo + hi) / 2, p = bend(loopProfile(g), 1);
      if (p[p.length - 1][0] - XJ > GAP) lo = g; else hi = g;
    }
    return loopProfile((lo + hi) / 2);
  })();
  function loopAt(k) { return bend(THETA, k); }

  var B_CIRCLE = samplePath("M128,140 A12,12 0 1 0 128,164 A12,12 0 1 0 128,140", NB);

  // Positions des gènes en mm depuis le début de chaque segment (d'après le dessin)
  var GENES = [
    { c: "A", a: 6.18, b: 8.59, k: "L", lab: ["L1"] },
    { c: "A", a: 10.26, b: 22.81, k: "V", lab: ["V", "λ", "1"] },
    { c: "A", a: 36.35, b: 38.76, k: "L", lab: ["L2"] },
    { c: "A", a: 40.34, b: 52.90, k: "V", lab: ["V", "λ", "2"], cutEnd: true },
    { c: "B", a: 21.5, b: 23.9, k: "L", lab: ["L"] },
    { c: "B", a: 25.3, b: 37.86, k: "V", lab: ["V", "λ", "30"] },
    { c: "C", a: 0.46, b: 2.89, k: "J", lab: ["J", "λ", "1"], cutStart: true },
    { c: "C", a: 5.52, b: 21.69, k: "C", lab: ["C", "λ", "1"] },
    { c: "C", a: 35.07, b: 37.50, k: "J", lab: ["J", "λ", "2"] },
    { c: "C", a: 39.91, b: 56.08, k: "C", lab: ["C", "λ", "2"] },
    { c: "C", a: 69.68, b: 72.11, k: "J", lab: ["J", "λ", "4"] },
    { c: "C", a: 74.54, b: 90.72, k: "C", lab: ["C", "λ", "4"] }
  ];
  var LEN = { A: LA, B: LB, C: LC };
  GENES.forEach(function (g) { g.a /= LEN[g.c]; g.b /= LEN[g.c]; });
  var BREAKS = [
    { c: "A", f: 3.34 / LA }, { c: "B", f: 8.3 / LB }, { c: "B", f: 47.6 / LB },
    { c: "C", f: 62.5 / LC }, { c: "C", f: 94.8 / LC }
  ];
  // Profil des bords déchirés (décalage le long du brin, de haut en bas)
  var ZIG = [0, 0.55, -0.25, 0.7, 0.05, 0.6, -0.2, 0.45, 0];

  // ---- Position de chaque segment à l'instant t (0 germinal, 1 boucle, 2 coupure, 3 jonction)
  function layout(t) {
    var P = { A: line(X0, LA, NA) };
    if (t <= 1) {
      P.B = loopAt(ease(t));
      var last = P.B[P.B.length - 1];
      P.C = line(last[0], LC, NC);
    } else {
      P.B = lerpPts(loopAt(1), B_CIRCLE, ease(t - 1));
      var cx = t <= 2 ? XJ + GAP : XJ + GAP + (C_FINAL - XJ - GAP) * ease((t - 2) / 0.8);
      P.C = line(cx, LC, NC);
    }
    return P;
  }

  function at(pts, frac) {
    var x = clamp(frac) * (pts.length - 1);
    var i = Math.min(Math.floor(x), pts.length - 2), f = x - i;
    var p = [pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f];
    var tx = pts[i + 1][0] - pts[i][0], ty = pts[i + 1][1] - pts[i][1], m = Math.hypot(tx, ty) || 1;
    tx /= m; ty /= m;
    return { p: p, t: [tx, ty], n: [ty, -tx] };
  }
  function sub(pts, f0, f1) {
    var out = [at(pts, f0).p], n = pts.length - 1;
    for (var i = Math.ceil(f0 * n + 1e-9); i <= Math.floor(f1 * n - 1e-9); i++) out.push(pts[i]);
    out.push(at(pts, f1).p);
    return out;
  }
  function f2(v) { return v.toFixed(3); }
  function ptsStr(a) { return a.map(function (p) { return f2(p[0]) + "," + f2(p[1]); }).join(" "); }
  function toD(pts) { return "M" + pts.map(function (p) { return f2(p[0]) + "," + f2(p[1]); }).join("L"); }
  function setLine(l, x1, y1, x2, y2) {
    l.setAttribute("x1", f2(x1)); l.setAttribute("y1", f2(y1));
    l.setAttribute("x2", f2(x2)); l.setAttribute("y2", f2(y2));
  }
  // Bord vertical (de +H à -H) à la position s, déchiré selon amp
  function edge(s, amp, sign) {
    var out = [];
    for (var i = 0; i < ZIG.length; i++) {
      var v = H - 2 * H * i / (ZIG.length - 1), o = ZIG[i] * amp * sign;
      out.push([s.p[0] + s.n[0] * v + s.t[0] * o, s.p[1] + s.n[1] * v + s.t[1] * o]);
    }
    return out;
  }

  // ---- Éléments
  var rib = {};
  ["A", "B", "C"].forEach(function (k) {
    rib[k] = {
      o: el("path", { stroke: COL.line, "stroke-width": RIB_OUT, "stroke-linecap": "butt" }, $(k === "B" ? "bOuter" : "strandOuter")),
      i: el("path", { stroke: COL.bg, "stroke-width": RIB_IN, "stroke-linecap": "butt" }, $(k === "B" ? "bInner" : "strandInner"))
    };
  });
  var FILL = { V: COL.V, J: COL.J, C: COL.C, L: COL.L };
  GENES.forEach(function (g) {
    g.poly = el("polygon", { fill: FILL[g.k], stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "miter" }, $(g.c === "B" ? "bGenes" : "genes"));
    var tx = el("text", { "text-anchor": "middle" }, $(g.c === "B" ? "bLabels" : "labels"));
    tx.appendChild(document.createTextNode(g.lab[0]));
    if (g.lab.length > 1) {
      el("tspan", { "font-size": "3.21px", dy: "1.1" }, tx).textContent = g.lab[1];
      el("tspan", { dy: "-1.1" }, tx).textContent = g.lab[2];
    }
    g.text = tx;
  });
  var insert = el("polygon", { fill: COL.INS, stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "miter" }, $("genes"));
  // Nucléotides insérés : de petits grains violets arrivent de tout autour et se rassemblent dans le trou
  var seed = 11;
  function rnd() { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; }
  var GRAINS = [];
  for (var gi = 0; gi < 40; gi++) {
    var ang = rnd() * Math.PI * 2, sz = 0.35 + rnd() * 0.45, nv = 3 + Math.floor(rnd() * 2), shp = [];
    for (var v = 0; v < nv; v++) { var av = (v + rnd() * 0.6) / nv * Math.PI * 2; shp.push([Math.cos(av) * sz, Math.sin(av) * sz]); }
    GRAINS.push({
      fx: 0.08 + rnd() * 0.84, fy: (rnd() * 2 - 1) * 0.85,
      dir: [Math.cos(ang), Math.sin(ang)], dist: 7 + rnd() * 9, swirl: (rnd() < 0.5 ? -1 : 1) * (0.2 + rnd() * 0.3),
      delay: rnd() * 0.45, rot: (rnd() * 2 - 1) * 260, shape: shp,
      el: el("polygon", { fill: COL.INS, stroke: "#5e3a7a", "stroke-width": 0.12, opacity: 0 }, $("debris"))
    });
  }
  var insLabel = el("text", { "text-anchor": "middle" }, $("notes"));
  insLabel.textContent = "N";
  BREAKS.forEach(function (b) {
    var g = el("g", {}, $(b.c === "B" ? "bBreaks" : "breaks"));
    b.fill = el("polygon", { fill: COL.bg, stroke: "none" }, g);
    b.l1 = el("line", { stroke: COL.line, "stroke-width": SW, "stroke-linecap": "square" }, g);
    b.l2 = el("line", { stroke: COL.line, "stroke-width": SW, "stroke-linecap": "square" }, g);
  });
  var cutMarks = [0, 1].map(function () { return el("line", { stroke: COL.cut, "stroke-width": 0.8, "stroke-linecap": "round" }, $("cuts")); });
  // Fragments arrachés aux extrémités : bout de gène + morceau de brin (RSS)
  var DEBRIS = [
    { side: "A", s: 52.4, fill: COL.V, shape: [[-0.5, -3.4], [0.6, -2.6], [0.4, 0.8], [-0.4, 0.2]], drift: [1.5, 9], rot: 40 },
    { side: "A", s: 52.6, fill: COL.V, shape: [[-0.4, 0.6], [0.5, 1.2], [0.3, 3.5], [-0.5, 3.2]], drift: [-1, 12], rot: -55 },
    { side: "A", s: 53.4, fill: COL.bg, shape: [[-0.6, -1.25], [0.6, -1.25], [0.6, 1.25], [-0.6, 1.25]], drift: [3, 7], rot: 70 },
    { side: "C", s: 0.8, fill: COL.J, shape: [[-0.4, -3.6], [0.5, -3.2], [0.3, 0.4], [-0.5, -0.2]], drift: [-1.5, 10], rot: -35 },
    { side: "C", s: 0.7, fill: COL.J, shape: [[-0.3, 0.3], [0.4, 0.8], [0.4, 3.6], [-0.4, 3.4]], drift: [1.5, 13], rot: 60 },
    { side: "C", s: 0.2, fill: COL.bg, shape: [[-0.4, -1.25], [0.4, -1.25], [0.4, 1.25], [-0.4, 1.25]], drift: [-2.5, 8], rot: -80 }
  ];
  DEBRIS.forEach(function (d) { d.el = el("polygon", { fill: d.fill, stroke: COL.line, "stroke-width": 0.3 }, $("debris")); });

  function render(t) {
    var P = layout(t);
    var trim = ease((t - 1.15) / 0.45);
    var endA = 1 - (TRIM_A / LA) * trim, startC = (TRIM_C / LC) * trim;

    var sA = sub(P.A, 0, endA), sC = sub(P.C, startC, 1);
    var dA = toD(sA), dB = toD(P.B), dC = toD(sC);
    // Aux extrémités 5′ et 3′, le trait blanc intérieur dépasse un peu pour masquer le bout noir du trait extérieur
    var a0 = at(P.A, 0), c1 = at(P.C, 1);
    var dAi = toD([[a0.p[0] - a0.t[0] * 0.4, a0.p[1] - a0.t[1] * 0.4]].concat(sA));
    var dCi = toD(sC.concat([[c1.p[0] + c1.t[0] * 0.4, c1.p[1] + c1.t[1] * 0.4]]));
    rib.A.o.setAttribute("d", dA); rib.A.i.setAttribute("d", dAi);
    rib.B.o.setAttribute("d", dB); rib.B.i.setAttribute("d", dB);
    rib.C.o.setAttribute("d", dC); rib.C.i.setAttribute("d", dCi);
    var bc = P.B.reduce(function (s, p) { return [s[0] + p[0] / P.B.length, s[1] + p[1] / P.B.length]; }, [0, 0]);

    GENES.forEach(function (g) {
      var pts = P[g.c], a = g.a, b = g.b;
      if (g.cutEnd) b = Math.min(b, endA);
      if (g.cutStart) a = Math.max(a, startC);
      // Gènes A et C rigides (passage du virage serré) : rectangle posé sur la tangente au milieu du gène, le brin seul se courbe
      var m = at(pts, (a + b) / 2), hl = (b - a) * LEN[g.c] / 2;
      var ea = { p: [m.p[0] - m.t[0] * hl, m.p[1] - m.t[1] * hl], t: m.t, n: m.n };
      var eb = { p: [m.p[0] + m.t[0] * hl, m.p[1] + m.t[1] * hl], t: m.t, n: m.n };
      function off(e, v) { return [e.p[0] + e.n[0] * v, e.p[1] + e.n[1] * v]; }
      var right = g.cutEnd && trim > 0 ? edge(eb, trim, 1) : [off(eb, H), off(eb, -H)];
      var left = g.cutStart && trim > 0 ? edge(ea, trim, -1).reverse() : [off(ea, -H), off(ea, H)];
      if (g.c === "B") {
        // Sur la boucle (grand rayon), le gène suit la courbure du brin
        var top = [], bot = [];
        for (var i = 0; i <= 8; i++) { var sb = at(pts, a + (b - a) * i / 8); top.push(off(sb, H)); bot.push(off(sb, -H)); }
        g.poly.setAttribute("points", ptsStr(top.concat(bot.reverse())));
      } else g.poly.setAttribute("points", ptsStr(right.concat(left)));
      var nx = m.n[0], ny = m.n[1];
      if (ny > 0) { nx = -nx; ny = -ny; }
      if (g.c === "B") {
        // Étiquettes de B : visibles sur le brin droit, effacées dès que la boucle se forme
        g.text.setAttribute("opacity", 1 - ease((t - 0.2) / 0.2));
      }
      var lo = 5.8 + 3.7 * Math.max(0, ny) + (g.c === "B" ? 2.5 * ease(t) : 0);
      g.text.setAttribute("x", f2(m.p[0] + nx * lo));
      g.text.setAttribute("y", f2(m.p[1] + ny * lo));
    });

    // Nucléotides insérés : les grains convergent vers le trou entre les bouts déchirés, puis
    // le bloc apparaît à leur place
    var sa = at(P.A, endA), sc = at(P.C, startC), coal = ease((t - 2.55) / 0.4);
    GRAINS.forEach(function (gr) {
      var e = ease((t - 2.05 - gr.delay) / 0.5);
      if (e <= 0 || coal >= 1) { gr.el.setAttribute("opacity", 0); return; }
      var tx = sa.p[0] + gr.fx * (sc.p[0] - sa.p[0]), ty = Y + gr.fy * H, k = 1 - e;
      var px = tx + gr.dir[0] * gr.dist * k - gr.dir[1] * gr.dist * gr.swirl * Math.sin(Math.PI * k);
      var py = ty + gr.dir[1] * gr.dist * k + gr.dir[0] * gr.dist * gr.swirl * Math.sin(Math.PI * k);
      var r = gr.rot * k * Math.PI / 180;
      gr.el.setAttribute("points", ptsStr(gr.shape.map(function (q) {
        return [px + q[0] * Math.cos(r) - q[1] * Math.sin(r), py + q[0] * Math.sin(r) + q[1] * Math.cos(r)];
      })));
      gr.el.setAttribute("opacity", Math.min(1, e * 3) * (1 - coal));
    });
    if (coal > 0) {
      var poly = [[sa.p[0], Y - H], [sc.p[0], Y - H]].concat(edge(sc, 1, -1), [[sa.p[0], Y + H]], edge(sa, 1, 1).reverse());
      insert.setAttribute("points", ptsStr(poly));
      insert.setAttribute("opacity", coal);
    } else {
      insert.setAttribute("points", "");
      insert.setAttribute("opacity", 0);
    }
    insLabel.setAttribute("x", f2((sa.p[0] + sc.p[0]) / 2));
    insLabel.setAttribute("y", f2(Y + 9.5));
    insLabel.setAttribute("opacity", clamp((t - 2.85) / 0.15));

    BREAKS.forEach(function (b) {
      var s = at(P[b.c], b.f), x = s.p[0], y = s.p[1], tx = s.t[0], ty = s.t[1], nx = s.n[0], ny = s.n[1];
      function pt(o, a) { return [x + tx * o + nx * a + tx * a * 0.45, y + ty * o + ny * a + ty * a * 0.45]; }
      var a1 = pt(-0.7, 2.7), a2 = pt(-0.7, -2.7), b1 = pt(0.7, 2.7), b2 = pt(0.7, -2.7);
      setLine(b.l1, a1[0], a1[1], a2[0], a2[1]);
      setLine(b.l2, b1[0], b1[1], b2[0], b2[1]);
      b.fill.setAttribute("points", ptsStr([a1, b1, b2, a2]));
    });

    var cutOp = Math.max(0, 1 - Math.abs(t - 1.12) / 0.2);
    [at(P.A, 1), at(P.C, 0)].forEach(function (s, i) {
      var x = s.p[0], y = s.p[1];
      setLine(cutMarks[i], x - 1.2, y - 3.6, x + 1.2, y + 3.6);
      cutMarks[i].setAttribute("opacity", cutOp);
    });

    var q = clamp((t - 1.15) / 0.8);
    DEBRIS.forEach(function (d) {
      if (q <= 0 || q >= 1) { d.el.setAttribute("opacity", 0); return; }
      var o = at(P[d.side], d.s / LEN[d.side]).p, qe = 1 - Math.pow(1 - q, 2);
      var cx = o[0] + d.drift[0] * qe, cy = o[1] + d.drift[1] * qe, r = d.rot * qe * Math.PI / 180;
      d.el.setAttribute("points", ptsStr(d.shape.map(function (p) {
        return [cx + p[0] * Math.cos(r) - p[1] * Math.sin(r), cy + p[0] * Math.sin(r) + p[1] * Math.cos(r)];
      })));
      d.el.setAttribute("opacity", 1 - q * q);
    });

    // Le cercle excisé s'efface simplement
    $("bGroup").setAttribute("opacity", 1 - ease((t - 1.45) / 0.6));

    renderVJC(t);
    renderCaptions(t, P);
  }

  // ---- Gènes réarrangés (t 3→4 : Igλ, t 4→5 : IgH déjà réarrangé) puis assemblage de l'anticorps (t 5→6)
  var ROW_X = X0 + 40.34;
  var ROWS = [
    { y: 133, t0: 3, label: "Igλ", segs: [
      { k: "V", w: 14.3, fill: COL.V }, { k: "N", w: 4.0, fill: COL.INS },
      { k: "J", w: 3.9, fill: COL.J }, { k: "C", w: 22, fill: COL.C, arrow: 6 }] },
    { y: 152, t0: 4, label: "IgH", segs: [
      { k: "V", w: 14.3, fill: COL.V }, { k: "N", w: 2.5, fill: COL.INS }, { k: "D", w: 4.2, fill: COL.D },
      { k: "N", w: 2.5, fill: COL.INS }, { k: "J", w: 3.9, fill: COL.J }, { k: "C", w: 40, fill: COL.C, arrow: 6 }] }
  ];
  ROWS.forEach(function (r) {
    r.g = el("g", {}, $("vjc"));
    r.els = r.segs.map(function (b) { return el("polygon", { fill: b.fill, stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "miter" }, r.g); });
    r.text = el("text", { "text-anchor": "middle" }, r.g);
    r.text.textContent = r.label;
    var x = ROW_X;
    r.segs.forEach(function (b) { b.x0 = x; b.x1 = x + b.w; x = b.x1; });
  });
  function rowRange(r, from, to) {
    var a = r.segs.filter(function (b) { return b.k === from; })[0], b = r.segs.filter(function (b) { return b.k === to; })[0];
    return [a.x0, b.arrow ? b.x1 - b.arrow : b.x1];
  }

  // Anticorps en Y. Dans chaque bras, la chaîne lourde est côté intérieur, la chaîne légère côté extérieur.
  // Étape 6 : une copie de chaque flèche (Igλ, IgH) glisse d'un seul tenant jusqu'à sa place dans l'anticorps,
  // la lourde se pliant à la charnière ; puis la structure (domaines, autres chaînes, charnière) apparaît.
  var AB = { x: 216, armY: 140, stemY: 141.5, ang: 42 * Math.PI / 180, DL: 12, DH: 6, off: 3.4, gap: 0.8, s0: 13 };
  var T_MOVE = 0.75, T_FADE = 0.75;          // en unités d'étape, à partir de t = 5
  function armFrame(side) {                  // side -1 = bras gauche, +1 = bras droit
    return { d: [side * Math.sin(AB.ang), -Math.cos(AB.ang)], pin: [-side * Math.cos(AB.ang), -Math.sin(AB.ang)] };
  }
  function armPoint(side, chain, s) {
    var f = armFrame(side), o = chain === "H" ? AB.off : -AB.off;
    return [AB.x + f.d[0] * s + f.pin[0] * o, AB.armY + f.d[1] * s + f.pin[1] * o];
  }
  function armDomain(side, chain, idx) {     // idx 0 = domaine constant (près du centre), 1 = variable
    var f = armFrame(side);
    return { c: armPoint(side, chain, AB.s0 + idx * (AB.DL + AB.gap)), a: Math.atan2(-f.d[1], -f.d[0]) * 180 / Math.PI };
  }
  function stemDomain(side, idx) {           // idx 0 = CH2, 1 = CH3
    return { c: [AB.x + side * AB.off, AB.stemY + AB.DL / 2 + idx * (AB.DL + AB.gap)], a: 90 };
  }
  var S_TIP = AB.s0 + AB.DL + AB.gap + AB.DL / 2, S_IN = AB.s0 - AB.DL / 2;
  var STEM_END = AB.stemY + 2 * AB.DL + AB.gap;

  // Trajet final de chaque chaîne (ligne médiane), du domaine V vers l'extrémité C
  var PATHS = [
    resample([armPoint(-1, "L", S_TIP), armPoint(-1, "L", S_IN)], 200),
    resample([armPoint(-1, "H", S_TIP), armPoint(-1, "H", S_IN), [AB.x - AB.off, AB.stemY], [AB.x - AB.off, STEM_END]], 300)
  ];
  // Ruban coloré de chaque flèche, qui se déplace de sa ligne vers son trajet final
  ROWS.forEach(function (r, ri) {
    var body = r.segs[r.segs.length - 1].x1 - r.segs[r.segs.length - 1].arrow - ROW_X;
    r.bodyLen = body;
    r.mv = el("g", { opacity: 0 }, $("ab"));
    r.mvEls = r.segs.map(function (b) { return el("polygon", { fill: b.fill, stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "round" }, r.mv); });
    r.mvHead = el("polygon", { fill: COL.C, stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "miter" }, r.mv);
    r.path = PATHS[ri];
  });

  // Structure finale : domaines arrondis. Les bandes N/J (légère) et D/J (lourde) sont au bout du
  // domaine V, côté site de liaison, posées en long et empilées comme dans le schéma de référence.
  var abG = el("g", { opacity: 0 }, $("ab"));
  var hingeG = el("g", { fill: "none", stroke: COL.line, "stroke-width": SW }, abG);
  var clipN = 0;
  // Contour d'un domaine. Les domaines V ont un bout découpé côté site de liaison (creux en U puis pente),
  // comme dans le schéma de référence ; les autres domaines sont des rectangles arrondis.
  function domainPath(isV) {
    var L = AB.DL, h = AB.DH, r = 1.6, x0 = -L / 2, x1 = L / 2, y0 = -h / 2, y1 = h / 2;
    var right = " H" + f2(x1 - r) + " A" + r + "," + r + " 0 0 0 " + f2(x1) + "," + f2(y1 - r) +
      " V" + f2(y0 + r) + " A" + r + "," + r + " 0 0 0 " + f2(x1 - r) + "," + f2(y0);
    if (!isV) return "M" + f2(x0 + r) + "," + f2(y0) + " A" + r + "," + r + " 0 0 0 " + f2(x0) + "," + f2(y0 + r) +
      " V" + f2(y1 - r) + " A" + r + "," + r + " 0 0 0 " + f2(x0 + r) + "," + f2(y1) + right + " Z";
    var uB = y0 + h * 0.5;                // bas du creux en U
    return "M" + f2(x0) + "," + f2(y0) +
      " C" + f2(x0 + 2.8) + "," + f2(y0) + " " + f2(x0 + 2.8) + "," + f2(uB) + " " + f2(x0) + "," + f2(uB) +
      " L" + f2(x0 + 2) + "," + f2(y1) + right + " Z";
  }
  // bars : bandes CDR au bout du domaine V, du côté intérieur du Y vers l'extérieur (null = rouge du V).
  // En travers du bras : V puis D puis J de la lourde, puis J puis V de la légère.
  function domain(dm, fill, bars, isV) {
    var g = el("g", { transform: "translate(" + f2(dm.c[0]) + "," + f2(dm.c[1]) + ") rotate(" + f2(dm.a) + ")" }, abG);
    var d = domainPath(isV);
    el("path", { d: d, fill: fill }, g);
    if (bars) {
      var id = "dclip" + (clipN++), cp = el("clipPath", { id: id }, g);
      el("path", { d: d }, cp);
      var bg = el("g", { "clip-path": "url(#" + id + ")" }, g), bh = AB.DH / bars.length;
      bars.forEach(function (b, i) {
        if (b) el("rect", { x: f2(-AB.DL / 2 - 0.5), y: f2(-AB.DH / 2 + i * bh), width: 5.6, height: f2(bh), fill: b, stroke: COL.line, "stroke-width": SW }, bg);
      });
    }
    el("path", { d: d, fill: "none", stroke: COL.line, "stroke-width": SW, "stroke-linejoin": "round" }, g);
  }
  // Charnière : chaque chaîne lourde relie son CH1 à son CH2 ; ponts disulfure légère–lourde et lourde–lourde
  [-1, 1].forEach(function (side) {
    var e1 = armPoint(side, "H", S_IN), e2 = [AB.x + side * AB.off, AB.stemY], e3 = armPoint(side, "L", S_IN);
    el("path", { d: "M" + f2(e1[0]) + "," + f2(e1[1]) + " L" + f2(e2[0]) + "," + f2(e2[1]) }, hingeG);
    el("path", { d: "M" + f2(e3[0]) + "," + f2(e3[1]) + " L" + f2(e1[0]) + "," + f2(e1[1]) }, hingeG);
  });
  el("path", { d: "M" + f2(AB.x - AB.off) + "," + f2(AB.stemY - 1.4) + " H" + f2(AB.x + AB.off) }, hingeG);
  // Chaînes issues des gènes (en couleur), bras gauche et colonne gauche du pied
  domain(armDomain(-1, "L", 1), COL.V, [COL.J, null], true);
  domain(armDomain(-1, "L", 0), COL.C);
  domain(armDomain(-1, "H", 1), COL.V, [null, COL.D, COL.J], true);
  domain(armDomain(-1, "H", 0), COL.C);
  domain(stemDomain(-1, 0), COL.C);
  domain(stemDomain(-1, 1), COL.C);
  // Autres chaînes (en blanc)
  [armDomain(1, "L", 1), armDomain(1, "L", 0), armDomain(1, "H", 1), armDomain(1, "H", 0), stemDomain(1, 0), stemDomain(1, 1)]
    .forEach(function (dm, i) { domain(dm, COL.bg, null, i === 0 || i === 2); });

  // Liste des étapes à gauche : chaque ligne apparaît au début de son étape et reste ;
  // l'étape en cours est en noir, les précédentes en gris
  var STEPS = [["Germline DNA"], ["RAG1/RAG2 cut,", "imprecise ends"], ["Formation of the", "random junction"],
    ["Rearranged gene"], ["Heavy chain gene,", "also rearranged"], ["Antibody assembly"]];
  var LIST_X = -26, LIST_Y = 104, LINE = 5, ITEM_GAP = 3.2;
  var capEls = [], ly = LIST_Y;
  STEPS.forEach(function (lines, k) {
    var g = el("g", { opacity: 0 }, $("captions"));
    var num = el("text", { x: LIST_X, y: ly, "class": "caption" }, g); num.textContent = (k + 1) + ".";
    lines.forEach(function (ln, i) {
      var tx = el("text", { x: LIST_X + 4.6, y: f2(ly + i * LINE), "class": "caption" }, g);
      tx.textContent = ln;
    });
    capEls.push({ g: g, y: ly, texts: g.querySelectorAll("text") });
    ly += lines.length * LINE + ITEM_GAP;
  });
  // Extrémités 5′ et 3′ du brin
  var end5 = el("text", { "class": "end", "text-anchor": "end" }, $("captions")); end5.textContent = "5′";
  var end3 = el("text", { "class": "end" }, $("captions")); end3.textContent = "3′";
  function renderCaptions(t, P) {
    capEls.forEach(function (c, k) {
      var on = k === 0 ? 1 : ease((t - (k - 0.15)) / 0.15);
      var past = k === STEPS.length - 1 ? 0 : clamp((t - (k + 1 - 0.15)) / 0.15);
      c.g.setAttribute("opacity", on);
      c.g.setAttribute("transform", "translate(" + f2(-2 * (1 - on)) + ",0)");
      var col = past > 0.5 ? "#9a9a9a" : "#000000";
      for (var i = 0; i < c.texts.length; i++) c.texts[i].style.fill = col;
    });
    var a0 = P.A[0], c1 = P.C[P.C.length - 1];
    end5.setAttribute("x", f2(a0[0] - 1.2)); end5.setAttribute("y", f2(a0[1] + 1.1));
    end3.setAttribute("x", f2(c1[0] + 1.2)); end3.setAttribute("y", f2(c1[1] + 1.1));
  }

  function bandPoly(path, f0, f1, h) {
    var top = [], bot = [], n = 10;
    for (var i = 0; i <= n; i++) {
      var s = at(path, f0 + (f1 - f0) * i / n);
      top.push([s.p[0] + s.n[0] * h, s.p[1] + s.n[1] * h]);
      bot.push([s.p[0] - s.n[0] * h, s.p[1] - s.n[1] * h]);
    }
    return top.concat(bot.reverse());
  }

  function renderVJC(t) {
    var mv = ease((t - 5) / T_MOVE);                   // déplacement des flèches vers l'anticorps
    var fadeArrows = clamp((t - 5 - T_MOVE) / 0.2);    // les flèches s'effacent quand la structure apparaît
    ROWS.forEach(function (r) {
      var a = ease((t - r.t0) / 0.5);
      var moving = t > 5;
      r.g.setAttribute("opacity", a);           // les gènes restent ; c'est une copie qui part former l'anticorps
      var y = r.y + 3 * (1 - a);
      r.segs.forEach(function (b, i) {
        var pts;
        if (b.arrow) {
          var xb = b.x1 - b.arrow;
          pts = [[b.x0, y - H], [xb, y - H], [b.x1, y], [xb, y + H], [b.x0, y + H]];
        } else pts = [[b.x0, y - H], [b.x1, y - H], [b.x1, y + H], [b.x0, y + H]];
        r.els[i].setAttribute("points", ptsStr(pts));
      });
      r.text.setAttribute("x", f2((ROW_X + r.segs[r.segs.length - 1].x1) / 2));
      r.text.setAttribute("y", f2(y + H + 6));

      // Flèche en mouvement : sa ligne médiane passe de la ligne droite au trajet dans l'anticorps
      if (!moving) { r.mv.setAttribute("opacity", 0); return; }
      r.mv.setAttribute("opacity", 1 - fadeArrows);
      var n = r.path.length, straight = [];
      for (var i = 0; i < n; i++) straight.push([ROW_X + r.bodyLen * i / (n - 1), r.y]);
      var cur = lerpPts(straight, r.path, mv), h = H + (AB.DH / 2 - H) * mv;
      r.segs.forEach(function (b, i) {
        var x1 = b.arrow ? b.x1 - b.arrow : b.x1;
        r.mvEls[i].setAttribute("points", ptsStr(bandPoly(cur, (b.x0 - ROW_X) / r.bodyLen, (x1 - ROW_X) / r.bodyLen, h)));
      });
      var e = at(cur, 1), hl = 6 + (3 - 6) * mv, hw = h;
      r.mvHead.setAttribute("points", ptsStr([
        [e.p[0] + e.n[0] * hw, e.p[1] + e.n[1] * hw], [e.p[0] + e.t[0] * hl, e.p[1] + e.t[1] * hl], [e.p[0] - e.n[0] * hw, e.p[1] - e.n[1] * hw]]));
    });
    abG.setAttribute("opacity", clamp((t - 5 - T_MOVE) / 0.2));
  }
  window.renderAt = render;
  var SEG = MOVES.map(function (m, k) { return HOLDS[k] + m; });
  var NST = MOVES.length, TOTAL = SEG.reduce(function (a, b) { return a + b; }, 0) + END_HOLD, start = null;
  function tAt(c) {
    for (var k = 0; k < NST; k++) {
      if (c < SEG[k]) return k + Math.max(0, c - HOLDS[k]) / MOVES[k];
      c -= SEG[k];
    }
    return NST;
  }
  render(0);
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) { render(NST); return; }
  function frame(now) {
    if (start === null) start = now;
    render(tAt(((now - start) / 1000) % TOTAL));
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
